export function KeyboardNavigation({
  orientation = "{{orientation}}",
  current = "{{current}}",
  accent = "{{accent}}",
  showNumbers = {{showNumbers}},
}) {
  const items = [
    { id: "item-1", n: 1, label: "Overview" },
    { id: "item-2", n: 2, label: "Reports" },
    { id: "item-3", n: 3, label: "Settings" },
  ];
  return (
    <div style={{ width: 320, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <div style={{ display: "flex", flexDirection: orientation === "vertical" ? "column" : "row", gap: 8 }}>
        {items.map((it) => (
          <a key={it.id} href="#" style={{
            display: "flex", alignItems: "center", gap: 6, padding: "9px 14px", borderRadius: 8,
            border: "1.5px solid #24143022", textDecoration: "none", color: "#241430",
            ...(current === it.id ? { outline: "2px solid " + accent, outlineOffset: 2, background: "#FAF7F2" } : {}),
          }}>
            {showNumbers && <span style={{ width: 16, height: 16, borderRadius: "50%", background: "#24143014", fontSize: 10, display: "grid", placeItems: "center", fontWeight: 700 }}>{it.n}</span>}
            {it.label}
          </a>
        ))}
      </div>
      <p style={{ marginTop: 12, fontSize: 12, color: "#241430aa" }}>{orientation === "vertical" ? "\u2193" : "\u2192"} arrow keys move focus &middot; current item ring shows focus</p>
    </div>
  );
}
